import {quantitySettingsFields,taskLevelFields,presetPanel,modePickerContent,recordPanel,weeklyPanel,scopeOptions,numberText} from './quantity-view.js';
import {createUniverse} from './universe.js';
import {LEVELS,nodePath,nodeDepth,visibleChildren,canPlace,freshUniverse,migrateUniverse,completeUniverse,reorderNode} from './universe-model.js';
import {MODES,dateKey,shiftDate,weekStart,seed,leaves,descendants,moveNode,deleteNode,setting,applyPending,plan,toggleLog,ancestry,stats,validate,measurement,unitInfo,validateMeasurement,setQuantity,removeQuantity,quantitySummary,validDateKey,applyMode,clearMode,modesForLevel} from './model.js';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let account=null;
try{const response=await fetch('/api/session',{cache:'no-store'});if(response.headers.get('content-type')?.includes('application/json')){const result=await response.json();if(result.mode==='google'){if(!response.ok||!result.user?.id){location.replace('/');throw Error('Authentication required')}account=result.user}}}catch(error){if(error.message==='Authentication required')throw error}
const storageKey=account?'jiku-v1:'+account.id:'jiku-v1';
let needsLegacyImport=false,storageLocked=false;let state;try{const raw=localStorage.getItem(storageKey);needsLegacyImport=!!account&&!raw&&!!localStorage.getItem('jiku-v1');state=raw?validate(JSON.parse(raw)):freshUniverse();if(raw&&!state.universe){localStorage.setItem(storageKey+':before-universe',raw);state=migrateUniverse(state)}}catch{storageLocked=true;state=state||freshUniverse();setTimeout(()=>toast('保存データを保護しています。設定からバックアップを確認してください。'),300)}
let treeScene=null,treeView=null,showGoalLabels=true,statsTab='quantity',quantityScope='all',statsWeek=weekStart(dateKey()),quantityDimension=null;
let view='tree',today=dateKey(),selected=today,month=today.slice(0,7),focus=null,zoom=1,pan={x:0,y:0};
function save(){if(storageLocked){toast('元の保存データを保護しています。バックアップを確認してください。');return false}try{localStorage.setItem(storageKey,JSON.stringify(state));return true}catch{toast('保存できませんでした。設定からバックアップを保存してください。');return false}}
applyPending(state,today);save();
const icon=(name)=>({home:'⌂',tree:'✧',calendar:'▦',stats:'◴',settings:'⚙'}[name]);
const names={tree:'自分の宇宙',stats:'統計'};
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function modal(html){const d=$('#dialog');d.innerHTML=html;d.showModal();d.querySelector('[autofocus]')?.focus()}
function close(){$('#dialog').close()}
function heading(k,title,sub,extra=''){return `<div class="page-heading"><div><div class="eyebrow">${k}</div><h1>${title}</h1><p>${sub}</p></div>${extra}</div>`}
function accountAvatar(){const picture=account?.picture;return `<span class="google-account-fallback" aria-hidden="true">G</span>${picture?`<img src="${esc(picture)}" alt="" referrerpolicy="no-referrer" data-account-photo>`:''}`}
function render(){document.body.classList.toggle('onboarding-active',view==='tree'&&!state.universe?.onboarded);if(treeScene){treeView=treeScene.getView();treeScene.dispose();treeScene=null}const latest=dateKey();if(today!==latest){if(statsWeek===weekStart(today))statsWeek=weekStart(latest);today=latest;selected=today;applyPending(state,today);save()}$('#app').innerHTML=`<main class="workspace view-${view}"><header class="topbar"><a class="brand" href="#tree" aria-label="jiku 自分の宇宙">jiku<span>●</span></a><button class="avatar" data-do="settings" aria-label="Googleアカウントと設定" title="Googleアカウントと設定">${accountAvatar()}</button></header><div class="content">${({tree:treePage,stats:statsPage}[view])()}</div></main><nav class="bottom-nav" aria-label="メインメニュー">${Object.entries(names).map(([k,v])=>`<button class="nav ${view===k?'active':''}" data-view="${k}" ${view===k?'aria-current="page"':''}><span aria-hidden="true">${icon(k)}</span><strong>${v}</strong></button>`).join('')}</nav>`;bindTree()}
function modeCards(key){const current=state.records[key]?.mode;return `<div class="mode-grid">${Object.entries(MODES).filter(([k])=>k!=='none').map(([k,m])=>`<button class="mode-card ${current===k?'selected':''} ${k}" data-mode="${k}" data-date="${key}"><span class="mode-icon">${m.icon}</span><span><strong>${m.label}</strong><small>${m.description}</small></span><span class="radio">${current===k?'✓':''}</span></button>`).join('')}</div>`}
function actionRow(n,key){const a=setting(state,n.id),done=!!state.logs[key]?.[n.id];return `<div class="action-row ${done?'done':''}"><button class="check ${done?'checked':''}" data-check="${esc(n.id)}" data-date="${key}" aria-label="${esc(n.name)}の実行記録" aria-pressed="${done}">${done?'✓':''}</button><div class="action-copy"><strong>${esc(n.name)}</strong><small>${esc(ancestry(state,n.id).slice(1,-1).join(' / ')||'自分の宇宙')}</small></div><span class="priority p${a.priority}">${['高','中','低'][a.priority]}</span><button class="edit-action" data-edit="${esc(n.id)}" aria-label="${esc(n.name)}を編集">⋯</button></div>`}
let navigating=false,onboardingTimer=null;
function currentSpace(){return state.nodes.find(n=>n.id===focus)||state.nodes.find(n=>n.parentId===null)}
function spaceTrail(){return nodePath(state,currentSpace().id).map((n,i)=>`<button data-space-enter="${esc(n.id)}" ${i===nodePath(state,currentSpace().id).length-1?'aria-current="location"':''}>${i===0?'宇宙':esc(n.name)}</button>`).join('<span>／</span>')}
function spaceHUD(){const n=currentSpace(),depth=nodeDepth(state,n.id),children=visibleChildren(state,n.id);return `<div class="universe-topline"><nav class="space-breadcrumb" aria-label="現在地">${spaceTrail()}</nav><button class="space-mode" data-do="today-mode">${MODES[state.records[today]?.mode]?.icon||'◌'} <span>${MODES[state.records[today]?.mode]?.label||'今日のモード'}</span></button></div><div class="space-heading"><div><span class="space-level">${String(Math.min(4,depth)+1).padStart(2,'0')} / 05 <i></i> ${LEVELS[Math.min(4,depth)]}全体</span><h1>${esc(n.name)}</h1>${depth===1?`<p class="space-symbol">中心核 · ${esc(n.symbolName||n.name)}</p>`:''}</div><button class="space-edit" data-edit="${esc(n.id)}" aria-label="${esc(n.name)}を編集">···</button></div><div class="space-primary-tools">${n.parentId?`<button data-space-enter="${esc(n.parentId)}" class="space-back">← <span>ひとつ上へ</span></button>`:'<span class="space-caption">YOUR OWN UNIVERSE</span>'}${depth<4?`<button class="space-add" data-space-add="${esc(n.id)}">＋ ${LEVELS[depth+1]}を追加</button>`:''}</div>${!children.length&&n.parentId?`<div class="space-empty"><span>この場所から、次の一歩へ。</span><button class="space-detail-button" data-space-detail="${esc(n.id)}">行動の設定を見る ↗</button></div>`:''}${depth>=4&&children.length?`<div class="space-legacy"><p>以前の5階層を超える目標は、元の構造とIDのまま保護しています。</p>${children.map(c=>`<button data-legacy-detail="${esc(c.id)}">${esc(c.name)} →</button>`).join('')}</div>`:''}<div class="space-bottom-tools"><button class="space-list-trigger" data-do="space-list">☷ <span>目標一覧</span></button><div class="space-camera"><button data-do="zoom-out" aria-label="縮小">−</button><span data-zoom-label>100%</span><button data-do="zoom-in" aria-label="拡大">＋</button><button data-do="reset-tree" aria-label="この階層の全体表示">⤢</button></div><button class="space-list-trigger" data-do="quick-actions">✧ <span>今日の行動</span></button></div>`}
function onboardingContent(){if(state.universe?.onboarded)return '';const step=state.universe?.step||'welcome';if(step==='welcome')return `<div class="cosmic-onboarding"><span class="onboard-kicker">EVERYTHING BEGINS WITH YOU</span><div class="origin-light"></div><h1>あなたの宇宙を、<br>はじめよう。</h1><p>望む未来に、あなただけの星を。</p><button class="cosmic-primary" data-do="big-bang">ビッグバンを起こす <span>↗</span></button><button class="onboard-skip" data-do="skip-bang">演出をスキップ</button></div>`;if(step==='bang')return `<div class="cosmic-onboarding big-bang"><div class="bang-core"></div>${Array.from({length:4},(_,i)=>`<div class="shockwave" style="--delay:${i*.24}s"></div>`).join('')}<div class="bang-nebula"></div><span class="bang-words">はじまりは、ひとつの光から。</span><button class="onboard-skip" data-do="skip-bang">演出をスキップ</button></div>`;return `<div class="cosmic-onboarding naming"><span class="onboard-kicker">${step==='galaxy'?'YOUR FIRST GALAXY':'NAME YOUR UNIVERSE'}</span><h1>${step==='galaxy'?'その未来につながる、<br>大きな目標を。':'この宇宙で、<br>あなたは何を目指しますか？'}</h1><form id="onboarding-form" data-step="${step}"><label class="sr-only">${step==='galaxy'?'最初の銀河の名前':'宇宙の名前'}</label><input name="cosmic-name" aria-label="${step==='galaxy'?'最初の銀河の名前':'宇宙の名前'}" maxlength="80" required placeholder="${step==='galaxy'?'例：優秀なエンジニアになる':'例：自分が望む人生を実現する'}" value="${step==='galaxy'?'':esc(state.universe?.draftName||'')}"><button class="cosmic-primary">${step==='galaxy'?'銀河を誕生させる':'次へ'} <span>→</span></button></form></div>`}
function treePage(){return `<section class="universe-scene full-panel" id="goal-tree" aria-label="自分の宇宙"><div class="universe-stage"></div><div class="space-travel-veil"></div><div class="universe-hud">${spaceHUD()}</div><div class="space-hint">天体をタップして内側へ · スワイプで移動</div>${onboardingContent()}</section>`}
async function enterSpace(id){if(navigating)return;const target=state.nodes.find(n=>n.id===id);if(!target)return;const depth=nodeDepth(state,id);if(depth>4){legacyDetail(id);return}const old=currentSpace(),direction=depth>nodeDepth(state,old.id)?1:-1;if(old.id===id)return;navigating=true;try{if(treeScene){const arrived=await treeScene.navigate(id,direction);if(!arrived)return}focus=id;const hud=$('.universe-hud');if(hud){hud.innerHTML=spaceHUD();const trail=hud.querySelector('.space-breadcrumb');if(trail)trail.scrollLeft=trail.scrollWidth;}if(!treeScene)render();if(depth===4)spaceDetail(id)}finally{navigating=false}}
function spaceDetail(id){const n=state.nodes.find(n=>n.id===id);if(!n)return;const hasChildren=visibleChildren(state,id).length>0,a=setting(state,id),m=measurement(state,id),level=a.modes.includes('rest')?'rest':a.modes.includes('busy')?'busy':'full';modal(`<div class="dialog-title"><div><div class="eyebrow">${esc(ancestry(state,id).slice(0,-1).join(' / '))}</div><h2>${esc(n.name)}</h2></div><button class="round-button" data-do="close" aria-label="閉じる">×</button></div>${n.description?`<p class="space-description">${esc(n.description)}</p>`:''}${!hasChildren?`<div class="space-action-metadata"><span>${MODES[level].icon} ${MODES[level].label}から</span><span>優先順位 ${['高','中','低'][a.priority]}</span>${m.dailyAmount?`<span>固定量 ${numberText(m.dailyAmount)}${esc(unitInfo(m).label)}</span>`:''}</div>`:''}<div class="space-detail-links"><button data-edit="${esc(id)}">目標を編集 <span>→</span></button>${!hasChildren?`<button data-open-preset="${esc(id)}">固定量・モードを設定 <span>→</span></button>`:''}<button data-space-stats="${esc(id)}">この目標の統計 <span>→</span></button>${!hasChildren?`<button data-record-leaf="${esc(id)}">今日の記録を調整 <span>→</span></button>`:''}</div>`)}
function legacyDetail(id){const n=state.nodes.find(n=>n.id===id);if(!n)return;modal(`<div class="dialog-title"><h2>${esc(n.name)}</h2><button class="round-button" data-do="close" aria-label="閉じる">×</button></div><p class="footnote">以前の階層です。履歴と親子関係は保持しています。新しい目標は5階層以内に作成できます。</p>${!hasChildren?`<div class="space-action-metadata"><span>${MODES[level].icon} ${MODES[level].label}から</span><span>優先順位 ${['高','中','低'][a.priority]}</span>${m.dailyAmount?`<span>固定量 ${numberText(m.dailyAmount)}${esc(unitInfo(m).label)}</span>`:''}</div>`:''}<div class="space-detail-links"><button data-edit="${esc(id)}">目標を編集 →</button>${!visibleChildren(state,id).length?`<button data-open-preset="${esc(id)}">行動設定 →</button>`:''}${visibleChildren(state,id).map(c=>`<button data-legacy-detail="${esc(c.id)}">${esc(c.name)} →</button>`).join('')}</div>`)}
function spaceList(){modal(`<div class="dialog-title"><h2>この場所の目標</h2><button class="round-button" data-do="close" aria-label="閉じる">×</button></div><div class="space-detail-links">${visibleChildren(state,currentSpace().id).map(n=>`<div class="space-list-row"><button data-space-go="${esc(n.id)}">${esc(n.name)} <span>↗</span></button><button data-space-reorder="${esc(n.id)}" data-direction="-1" aria-label="${esc(n.name)}を前へ">↑</button><button data-space-reorder="${esc(n.id)}" data-direction="1" aria-label="${esc(n.name)}を後へ">↓</button><button data-edit="${esc(n.id)}" aria-label="${esc(n.name)}を編集">···</button></div>`).join('')||'<p class="muted">まだ下位目標はありません。</p>'}</div>`)}
function beginBang(skip=false){clearTimeout(onboardingTimer);state.universe.step=skip||matchMedia('(prefers-reduced-motion: reduce)').matches?'universe-name':'bang';save();render();if(state.universe.step==='bang')treeScene?.burst();if(state.universe.step==='bang')onboardingTimer=setTimeout(()=>{if(state.universe.step==='bang'){state.universe.step='universe-name';save();render()}},3900)}
function calendarPage(){const [y,m]=month.split('-').map(Number),first=`${month}-01`,offset=(new Date(first+'T12:00:00+09:00').getUTCDay()+6)%7,num=new Date(Date.UTC(y,m,0)).getUTCDate(),weeks=Math.ceil((num+offset)/7);return `<section class="calendar-card full-panel" aria-label="活動カレンダー"><div class="month-heading"><h1>${y}<small>年</small> ${m}<small>月</small></h1><div><button class="round-button" data-month="-1" aria-label="前の月">←</button><button class="text-button" data-do="today">今月</button><button class="round-button" data-month="1" aria-label="次の月">→</button></div></div><div class="calendar-grid" style="--weeks:${weeks}">${['月','火','水','木','金','土','日'].map(d=>`<span class="day-label">${d}</span>`).join('')}${'<div></div>'.repeat(offset)}${Array.from({length:num},(_,i)=>{const k=`${month}-${String(i+1).padStart(2,'0')}`,mode=state.records[k]?.mode,activity=quantitySummary(state,k,k,quantityScope,false).entries.length;return `<button class="day-cell ${selected===k?'selected':''} ${k===today?'today':''}" data-select-date="${k}" aria-label="${m}月${i+1}日 ${MODES[mode]?.label||'未記録'}" ${k>today?'disabled':''}><span>${i+1}</span><i style="background:${MODES[mode]?.color||'#eeede6'}">${mode?MODES[mode].icon:''}</i>${activity?'<b class="quantity-calendar-dot"></b>':''}</button>`}).join('')}</div><div class="legend">${Object.values(MODES).map(m=>`<span><i style="background:${m.color}"></i>${m.label}</span>`).join('')}<span><i style="background:#eeede6"></i>未記録</span></div></section>`}
function dayEditor(key){selected=key;const summary=quantitySummary(state,key,key,quantityScope,false);modal(`<div class="dialog-title"><h2>${Number(key.slice(5,7))}月${Number(key.slice(8))}日</h2><button class="round-button" data-do="close" aria-label="閉じる">×</button></div><section class="day-quantity"><div class="section-title"><h3>取り組んだ量</h3><button class="text-button" data-pick-leaf="${key}">＋ 記録する</button></div>${summary.entries.map(l=>`<div class="day-quantity-row"><span>${esc(l.name)}</span><strong>${numberText(l.amount)}<small>${esc(l.unit)}</small></strong>${state.nodes.some(n=>n.id===l.id)?`<button class="text-button" data-record-leaf="${esc(l.id)}" data-log-date="${key}">編集</button>`:''}</div>`).join('')||'<p class="muted">量の記録はありません。</p>'}</section><details class="daily-mode-details"><summary>この日のモード</summary><div class="day-modes">${Object.entries(MODES).map(([k,m])=>`<button class="${state.records[key]?.mode===k?'chosen':''}" data-mode="${k}" data-date="${key}"><span style="color:${m.color}">${m.icon}</span>${m.label}<i>${state.records[key]?.mode===k?'✓':''}</i></button>`).join('')}</div><button class="text-button quiet" data-do="clear-record">モードを未記録に戻す</button></details>`)}
function rhythmPage(){const start=shiftDate(today,-29),s=stats(state,start,today),counts=s.counts;return `<section class="rhythm-panel full-panel" aria-label="日々のモードの割合"><h1>日々のモードの割合</h1><div class="distribution" role="img" aria-label="記録した${s.days}日間のモードの割合">${s.days?Object.entries(counts).map(([k,c])=>`<div style="width:${c/s.days*100}%;background:${MODES[k].color}" title="${MODES[k].label}: ${c}日"></div>`).join(''):'<div style="width:100%;background:#eeede6"></div>'}</div><div class="rhythm-rows">${Object.entries(counts).map(([k,c])=>`<div class="distribution-row"><i style="background:${MODES[k].color}"></i><span>${MODES[k].label}</span><strong>${c}<small>日</small></strong><em>${s.days?Math.round(c/s.days*100):0}%</em></div>`).join('')}</div><p class="footnote">未記録 ${30-s.days} 日は割合に含めていません。</p></section>`}
function statsPage(){if(quantityScope!=='all'&&!state.nodes.some(n=>n.id===quantityScope))quantityScope='all';return `<section class="statistics-workspace"><div class="statistics-toolbar"><div class="statistics-tabs" role="tablist" aria-label="統計の表示"><button role="tab" aria-selected="${statsTab==='quantity'}" data-stat-tab="quantity">今週</button><button role="tab" aria-selected="${statsTab==='calendar'}" data-stat-tab="calendar">カレンダー</button></div>${statsTab==='quantity'?`<label class="statistics-scope"><span class="sr-only">振り返る目標</span><select id="quantity-scope" aria-label="振り返る目標">${scopeOptions(state,quantityScope)}</select></label>`:'<button class="text-button rhythm-link" data-do="show-rhythm">モードの割合 ↗</button>'}</div><div class="statistics-content ${statsTab==='calendar'?'calendar-content':'quantity-content'}">${statsTab==='calendar'?calendarPage():weeklyPanel(state,{week:statsWeek,scope:quantityScope,dimension:quantityDimension,today})}</div></section>`}

function leafPanel(id,key=today){if(!state.nodes.some(n=>n.id===id))return;modal(recordPanel(state,id,key,today))}
function openNode(id){enterSpace(id)}
function openPreset(id){modal(presetPanel(state,id))}
function modePicker(){modal(modePickerContent(state,today))}
function parseMeasure(f){const m={unit:f.get('quantity-unit'),customUnit:String(f.get('custom-unit')||'').trim(),dailyAmount:f.get('daily-amount')===''?null:Number(f.get('daily-amount')),weeklyTarget:f.get('weekly-target')===''?null:Number(f.get('weekly-target'))};validateMeasurement(m);return m}
function refreshTodayMode(){if(state.records[today]?.mode)applyMode(state,today,state.records[today].mode,today)}
function chooseLeaf(key){const available=leaves(state).filter(n=>quantityScope==='all'||descendants(state,quantityScope).has(n.id));modal(`<div class="dialog-title"><h2>行動を選ぶ</h2><button class="round-button" data-do="close" aria-label="閉じる">×</button></div><div class="record-leaf-picker">${available.map(n=>`<button data-record-leaf="${esc(n.id)}" data-log-date="${key}"><span>♧</span>${esc(n.name)}<i>＋</i></button>`).join('')||'<p class="muted">この目標には行動がありません。</p>'}</div>`)}
let addParent=null;
function editor(id){const isNew=id==='new',parent=addParent||currentSpace().id,n=isNew?{name:'',description:'',parentId:parent}:state.nodes.find(n=>n.id===id);if(!n)return;const a=isNew?{priority:1,type:'continuous',status:'active',modes:['full']}:setting(state,id),isRoot=!isNew&&!n.parentId,blocked=isNew?new Set():descendants(state,id),isLeaf=isNew||leaves(state).some(n=>n.id===id),depth=isNew?nodeDepth(state,parent)+1:nodeDepth(state,id);if(isNew&&depth>4){toast('目標は宇宙から衛星までの5階層です');return}modal(`<form id="node-form" data-id="${esc(id)}"><div class="dialog-title"><div><div class="eyebrow">${LEVELS[Math.min(depth,4)]}</div><h2>${isNew?'新しい'+LEVELS[depth]:isRoot?'宇宙を編集':'目標を編集'}</h2></div><button type="button" data-do="close" class="round-button" aria-label="閉じる">×</button></div><label>名前<input autofocus required maxlength="80" name="name" value="${esc(n.name)}" placeholder="目指したいことを、自分の言葉で"></label><label>説明<textarea name="description" maxlength="1000" rows="2" placeholder="この目標に込めた思い">${esc(n.description||'')}</textarea></label>${depth===1?`<label>ブラックホールの名前<input name="symbol-name" maxlength="80" value="${esc(n.symbolName||n.name)}" placeholder="銀河の中心核の名前"></label>`:''}${!isRoot?`<label>つながる上位目標<select name="parent">${state.nodes.filter(p=>!blocked.has(p.id)&&(p.id===n.parentId||canPlace(state,isNew?'new':id,p.id))).map(p=>`<option value="${esc(p.id)}" ${p.id===n.parentId?'selected':''}>${esc(ancestry(state,p.id).join(' / '))}</option>`).join('')}</select></label>`:''}${isLeaf?`<details class="cosmic-action-settings"><summary>この目標の行動設定</summary><div class="form-columns"><label>種類<select name="type"><option value="continuous" ${a.type==='continuous'?'selected':''}>継続型</option><option value="once" ${a.type==='once'?'selected':''}>完了型</option></select></label><label>優先順位<select name="priority">${['高','中','低'].map((p,i)=>`<option value="${i}" ${i===a.priority?'selected':''}>${p}</option>`).join('')}</select></label></div><label>状態<select name="status">${Object.entries({active:'有効',paused:'一時停止',completed:'完了'}).map(([v,t])=>`<option value="${v}" ${v===a.status?'selected':''}>${t}</option>`).join('')}</select></label>${quantitySettingsFields(state,id,false)}${taskLevelFields(a)}</details>`:`<p class="footnote">下位目標 ${visibleChildren(state,id).length}件${state.settings[id]?' · 以前の行動設定は保持しています':''}</p>`}<div class="dialog-actions">${!isNew&&!isRoot?`<button type="button" class="danger text-button" data-delete="${esc(id)}">削除</button>`:''}${!isNew?`<button type="button" class="text-button" data-space-stats="${esc(id)}">統計を見る</button>`:''}<button class="primary" type="submit">${isNew?'誕生させる':'保存する'}</button></div></form>`)}
function review(){const ws=weekStart(today),end=shiftDate(ws,6),s=stats(state,ws,end),r=state.reviews[ws]||{},effective=shiftDate(ws,7);modal(`<form id="review-form"><div class="dialog-title"><div><div class="eyebrow">WEEKLY REFLECTION</div><h2>今週の自分と、話そう。</h2></div><button type="button" data-do="close" class="round-button" aria-label="閉じる">×</button></div><p class="muted">${ws.replaceAll('-','/')} — ${end.replaceAll('-','/')}</p><div class="review-summary">${Object.entries(s.counts).map(([k,c])=>`<div><span style="color:${MODES[k].color}">${MODES[k].icon}</span><strong>${c}日</strong><small>${MODES[k].label}</small></div>`).join('')}</div><h3>今週、取り組んだ行動</h3><p class="muted">${s.logs.length} 回の実行記録</p>${Object.entries(s.logs.reduce((o,l)=>(o[l.name]=(o[l.name]||0)+1,o),{})).map(([n,c])=>`<p class="review-log">♧ ${esc(n)} <b>${c}回</b></p>`).join('')}<label>無理があったこと・気づいたこと<textarea name="note" rows="3" placeholder="今週の自分に、どんな言葉をかけたい？">${esc(r.note||'')}</textarea></label><label>来週、大切にしたいこと<textarea name="next" rows="2" placeholder="小さく、具体的な一歩を書いてみよう。">${esc(r.next||'')}</textarea></label><h3>来週の行動プラン</h3><p class="footnote">${effective.replaceAll('-','/')}（月）から反映。過去の記録はそのまま残ります。</p>${leaves(state).map(n=>{const a=state.pending.find(p=>p.id===n.id&&p.effective===effective)?.setting||setting(state,n.id);return `<fieldset class="review-setting" data-review-node="${esc(n.id)}"><legend>${esc(n.name)}</legend><select aria-label="${esc(n.name)}の来週の優先順位" data-review-priority>${['高','中','低'].map((p,i)=>`<option value="${i}" ${a.priority===i?'selected':''}>優先順位：${p}</option>`).join('')}</select>${taskLevelFields(a,'review-level-'+n.id)}</fieldset>`}).join('')}<div class="dialog-actions"><button class="primary">レビューを保存</button></div></form>`)}
function settings(){modal(`<div class="dialog-title"><div><div class="eyebrow">YOUR OWN UNIVERSE</div><h2>設定・バックアップ</h2></div><button class="round-button" data-do="close" aria-label="閉じる">×</button></div>${account?`<div class="account-info"><div class="account-profile-photo">${accountAvatar()}</div><strong>${esc(account.name)}</strong><p>${esc(account.email)}</p>${!account.picture?'<a class="text-button" href="/api/auth/google">Googleのプロフィール画像を取得</a>':''}<form method="post" action="/api/auth/logout" data-native-submit><button class="text-button" type="submit">ログアウト</button></form></div>`:''}<p>データはこの端末・ブラウザ内に保存されます。端末間での同期はありません。ブラウザのデータを消す前にバックアップしてください。</p><button class="text-button" data-do="review">今週を振り返る →</button><div class="settings-actions"><button class="primary" data-do="export">↓ バックアップを書き出す</button><label class="import-button">↑ バックアップを読み込む<input type="file" id="import" accept="application/json,.json"></label></div><p class="footnote">読み込み時は現在のデータを置き換えます。先に現在のバックアップを保存することをおすすめします。日付は日本時間、週の始まりは月曜日です。</p><hr><p class="muted">jiku v1.0 · 自分の軸を、日々の行動へ。</p>`)}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-do],[data-view],[data-day],[data-focus]');if(!b)return;const d=b.dataset;if(d.spaceEnter){enterSpace(d.spaceEnter);return}if(d.spaceGo){close();enterSpace(d.spaceGo);return}if(d.legacyDetail){legacyDetail(d.legacyDetail);return}if(d.spaceAdd){addParent=d.spaceAdd;editor('new');return}if(d.spaceDetail){spaceDetail(d.spaceDetail);return}if(d.spaceStats){quantityScope=d.spaceStats;statsTab='quantity';view='stats';location.hash='stats';close();render();return}if(d.spaceReorder){reorderNode(state,d.spaceReorder,Number(d.direction));save();render();spaceList();return}if(d.openPreset)openPreset(d.openPreset);if(b.hasAttribute('data-configure-leaves')){close();view='tree';location.hash='tree';render();toast('行動を押して、タスクの固定量を設定してください')}if(d.recordLeaf)leafPanel(d.recordLeaf,d.logDate||today);if(d.pickLeaf)chooseLeaf(d.pickLeaf);if(d.quantityDay)dayEditor(d.quantityDay);if(d.quantityWeek){statsWeek=shiftDate(statsWeek,Number(d.quantityWeek)*7);render()}if(b.hasAttribute('data-reset-week')){statsWeek=weekStart(today);render()}if(d.quantityDimension){quantityDimension=d.quantityDimension;render()}if(d.addQuantity){const input=$('#quantity-form [name=amount]');if(input)input.value=String(Math.round(((Number(input.value)||0)+Number(d.addQuantity))*1000000)/1000000)}if(d.removeQuantity){modal(`<h2>この日の量の記録を削除しますか？</h2><div class="dialog-actions"><button class="text-button" data-do="close">キャンセル</button><button class="primary danger-bg" data-confirm-remove-quantity="${esc(d.removeQuantity)}" data-log-date="${d.logDate}">削除する</button></div>`)}if(d.confirmRemoveQuantity){removeQuantity(state,d.logDate,d.confirmRemoveQuantity);save();close();render();toast('この日の記録を削除しました')}if(b.hasAttribute('data-scroll-tree')){$('#goal-tree')?.scrollIntoView({behavior:'smooth',block:'start'})}if(d.statTab){statsTab=d.statTab;render()}if(d.view){view=d.view;location.hash=view;render();window.scrollTo(0,0)}if(d.mode){try{const count=applyMode(state,d.date,d.mode,today);save();render();close();toast(count?`${count}個のタスクの固定量を反映しました`:'モードを保存しました')}catch(error){toast(error.message)}}if(d.check){const n=state.nodes.find(n=>n.id===d.check);if(n){toggleLog(state,d.date,n);save();render()}}if(d.edit){addParent=null;editor(d.edit);if(b.hasAttribute('data-quantity-settings'))$('#node-form [name=quantity-unit]')?.focus()}if(d.selectDate){selected=d.selectDate;render();dayEditor(selected)}if(d.day){selected=d.day;month=selected.slice(0,7);view='stats';statsTab='calendar';render()}if(d.month){const [y,m]=month.split('-').map(Number),v=new Date(Date.UTC(y,m-1+Number(d.month),1));month=`${v.getUTCFullYear()}-${String(v.getUTCMonth()+1).padStart(2,'0')}`;render()}if(d.focus){focus=d.focus;treeView=null;treeScene?.dispose();treeScene=null;zoom=1;pan={x:0,y:0};close();render()}if(d.delete){const id=d.delete,n=state.nodes.find(n=>n.id===id),count=descendants(state,id).size;modal(`<h2>「${esc(n.name)}」を削除しますか？</h2><p>子孫を含め ${count} 個の目標を削除します。過去の実行記録は残ります。</p><div class="dialog-actions"><button class="text-button" data-do="close">キャンセル</button><button class="primary danger-bg" data-confirm-delete="${esc(id)}">削除する</button></div>`)}if(d.confirmDelete){deleteNode(state,d.confirmDelete);focus=null;treeScene?.dispose();treeScene=null;treeView=null;save();close();render();toast('目標を削除しました')}if(d.do)({close,settings,review,'space-list':spaceList,'quick-actions':()=>chooseLeaf(today),'big-bang':()=>beginBang(),'skip-bang':()=>beginBang(true),'show-rhythm':()=>modal(`<div class="dialog-title"><h2>モードの割合</h2><button class="round-button" data-do="close" aria-label="閉じる">×</button></div>${rhythmPage()}`),'today-mode':modePicker,'labels':()=>{showGoalLabels=!showGoalLabels;applyLabelVisibility();b.setAttribute('aria-pressed',String(showGoalLabels))},'zoom-in':()=>{if(treeScene)treeScene.zoom(1.25);else{zoom=Math.min(2.5,zoom+.2);render()}},'zoom-out':()=>{if(treeScene)treeScene.zoom(.8);else{zoom=Math.max(.4,zoom-.2);render()}},'reset-tree':()=>{if(focus){focus=null;treeScene?.dispose();treeScene=null;treeView=null;render()}else if(treeScene)treeScene.reset();else{zoom=1;pan={x:0,y:0};render()}},today:()=>{month=today.slice(0,7);selected=today;render()},'clear-record':()=>{clearMode(state,selected);save();render();close();toast('モードを未記録に戻しました')},export:()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=`jiku-backup-${today}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}[d.do])?.()});
document.addEventListener('error',e=>{if(e.target.matches?.('[data-account-photo]'))e.target.remove()},true);
document.addEventListener('submit',e=>{if(e.target.hasAttribute('data-native-submit'))return;e.preventDefault();if(e.target.id==='onboarding-form'){const f=new FormData(e.target),name=String(f.get('cosmic-name')||'').trim();if(!name)return;const previous=structuredClone(state);if(e.target.dataset.step==='galaxy'){const id=completeUniverse(state,state.universe.draftName||state.nodes.find(n=>!n.parentId).name,name);if(save()){close();render();treeScene?.birth(id);toast('最初の銀河が誕生しました')}else state=previous}else{state.universe={...state.universe,step:'galaxy',draftName:name};if(save())render();else state=previous}}if(e.target.id==='node-form'){const f=new FormData(e.target),id=e.target.dataset.id,newId=id==='new'?crypto.randomUUID():id,name=String(f.get('name')||'').trim();if(!name){toast('名前を入力してください');return}const previous=structuredClone(state);try{let measure=null;if(f.has('quantity-unit'))measure=parseMeasure(f);const parent=f.get('parent'),existing=state.nodes.find(n=>n.id===id);if((id==='new'||existing?.parentId!==parent)&&f.has('parent')&&!canPlace(state,id,parent))throw Error('目標は宇宙から衛星までの5階層以内にしてください');if(id==='new')state.nodes.push({id:newId,parentId:parent,name,description:String(f.get('description')||''),symbolName:String(f.get('symbol-name')||name)});else{if(existing.parentId)moveNode(state,id,parent);existing.name=name;existing.description=String(f.get('description')||'');if(f.has('symbol-name'))existing.symbolName=String(f.get('symbol-name')||name)}if(f.has('type'))state.settings[newId]={...setting(state,newId),measurement:measure,type:f.get('type'),priority:Number(f.get('priority')),status:f.get('status'),modes:modesForLevel(f.get('task-level'))};refreshTodayMode();if(!save()){state=previous;return}close();render();if(id==='new')treeScene?.birth(newId);toast(id==='new'?'新しい天体が誕生しました':'目標を更新しました')}catch(err){state=previous;toast(err.message)}}if(e.target.id==='preset-form'){const f=new FormData(e.target),id=e.target.dataset.id;try{const m=parseMeasure(f);if(m.dailyAmount==null)throw Error('タスクの固定量を入力してください');state.settings[id]={...setting(state,id),measurement:m,modes:modesForLevel(f.get('task-level'))};refreshTodayMode();save();close();render();toast('タスクの固定量を保存しました')}catch(error){toast(error.message)}}if(e.target.id==='quantity-form'){const f=new FormData(e.target);try{setQuantity(state,f.get('record-date'),e.target.dataset.id,Number(f.get('amount')));save();close();render();toast('取り組んだ量を記録しました')}catch(error){toast(error.message)}}if(e.target.id==='review-form'){const ws=weekStart(today),effective=shiftDate(ws,7),f=new FormData(e.target);state.reviews[ws]={note:f.get('note'),next:f.get('next'),savedAt:new Date().toISOString()};e.target.querySelectorAll('[data-review-node]').forEach(el=>{const id=el.dataset.reviewNode;state.pending=state.pending.filter(p=>!(p.id===id&&p.effective===effective));state.pending.push({id,effective,setting:{...setting(state,id),priority:Number(el.querySelector('select').value),modes:modesForLevel(el.querySelector('input:checked').value)}})});save();close();render();toast('レビューを保存しました。行動設定は来週から反映します。')}});
document.addEventListener('change',async e=>{if(e.target.id==='quantity-scope'){quantityScope=e.target.value;render()}if(e.target.matches('[data-quantity-unit]')){e.target.closest('form').querySelector('[data-custom-unit]').hidden=e.target.value!=='custom'}if(e.target.name==='record-date'&&validDateKey(e.target.value)&&e.target.value<=today){leafPanel(e.target.closest('form').dataset.id,e.target.value)}if(e.target.id==='import'&&e.target.files[0]){try{const f=e.target.files[0];if(f.size>10*1024*1024)throw Error('10MB以下のバックアップを選んでください');const next=validate(JSON.parse(await f.text()));modal(`<h2>バックアップを読み込みますか？</h2><p>${next.nodes.length} 個の目標を読み込み、現在のデータを置き換えます。</p><div class="dialog-actions"><button class="text-button" data-do="close">キャンセル</button><button id="confirm-import" class="primary">置き換える</button></div>`);$('#confirm-import').onclick=()=>{state=migrateUniverse(next);storageLocked=false;focus=null;applyPending(state,today);focus=null;save();close();render();toast('バックアップを読み込みました')}}catch(err){toast('読み込めませんでした：'+err.message)}}});
function bindTree(){const host=$('.universe-stage');if(!host)return;try{treeScene=createUniverse(host,{nodes:state.nodes,current:currentSpace().id,onSelect:openNode,onZoom:value=>{const label=$('[data-zoom-label]');if(label)label.textContent=value+'%'}})}catch(error){host.innerHTML=`<div class="universe-fallback"><p>この端末では、目標一覧で宇宙を探索できます。</p>${visibleChildren(state,currentSpace().id).map(n=>`<button data-space-enter="${esc(n.id)}">✧ ${esc(n.name)} →</button>`).join('')}</div>`}}
function applyLabelVisibility(){}
$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
window.addEventListener('hashchange',()=>{const raw=location.hash.slice(1),h=raw==='home'?'tree':raw==='calendar'?'stats':raw;if(raw==='calendar')statsTab='calendar';if(names[h]&&(view!==h||raw==='calendar')){view=h;render()}});window.addEventListener('focus',()=>{if(dateKey()!==today){render();if(state.universe?.onboarded&&!state.records[today]?.quantityMenu)modePicker()}});if(names[location.hash.slice(1)])view=location.hash.slice(1);if(location.hash==='#home')history.replaceState(null,'','#tree');if(location.hash==='#calendar'){view='stats';statsTab='calendar';history.replaceState(null,'','#stats')}render();if(state.universe?.step==='bang')beginBang(true);if(needsLegacyImport)offerLegacyImport();else if(state.universe?.onboarded&&!state.records[today]?.quantityMenu)modePicker();

function offerLegacyImport(){modal(`<div class="dialog-title"><h2>以前の記録を引き継ぎますか？</h2></div><p>このブラウザでGoogleログイン前に使っていた記録が残っています。現在ログインしているあなたのアカウントへコピーできます。</p><p class="footnote">元の記録はそのまま残ります。</p><div class="dialog-actions"><button class="text-button" data-do="close">新しく始める</button><button id="copy-legacy" class="primary">記録を引き継ぐ</button></div>`);$('#copy-legacy').onclick=()=>{try{const old=localStorage.getItem('jiku-v1');localStorage.setItem(storageKey+':before-universe',old);state=migrateUniverse(validate(JSON.parse(old)));applyPending(state,today);save();close();render();toast('以前の記録を引き継ぎました');if(state.universe?.onboarded&&!state.records[today]?.quantityMenu)modePicker()}catch{toast('以前の記録を読み込めませんでした。バックアップから読み込んでください。')}}}
